<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cèlè One Admin</title><style>body{font-family:system-ui;margin:0;background:#f4f7f9;color:#123142}header{background:#123142;color:#fff;padding:18px 28px;display:flex;justify-content:space-between;align-items:center}.brand{color:#58d2d5}button{background:#2fa5a9;color:#fff;border:0;padding:10px 14px;border-radius:8px}.main{padding:24px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px}.card,.panel{background:#fff;padding:18px;border-radius:14px;box-shadow:0 3px 18px #12314212}.number{font-size:28px;font-weight:900;color:#2fa5a9}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:18px;margin-top:18px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid #e2e8f0}.domains{display:flex;flex-wrap:wrap;gap:8px}.domains a{padding:8px 11px;border-radius:20px;background:#e5f7f7;color:#12676a;text-decoration:none;font-size:13px}</style></head><body><header><h1><span class="brand">CÈLÈ ONE</span> Administration</h1><form method="post" action="/admin/logout">@csrf<button>Sign out</button></form></header><main class="main"><div class="cards">@foreach($counts as $label=>$value)<div class="card"><strong>{{ ucfirst(str_replace('_',' ',$label)) }}</strong><div class="number">{{ number_format($value) }}</div></div>@endforeach</div><div class="grid"><section class="panel"><h2>Recent users</h2><table><tr><th>Name</th><th>Email</th><th>Role</th></tr>@foreach($users as $user)<tr><td>{{ $user->name }}</td><td>{{ $user->email }}</td><td>{{ $user->role }}</td></tr>@endforeach</table></section><section class="panel"><h2>Recent posts</h2><table><tr><th>Author</th><th>Type</th><th>Status</th></tr>@foreach($posts as $post)<tr><td>{{ $post->user?->name ?? 'Unknown' }}</td><td>{{ $post->post_type }}</td><td>{{ $post->status }}</td></tr>@endforeach</table></section></di